AGGREGATE_FUNCTIONS = ("sum", "min", "max", "mean")


def parse_aggregate(arg):
    """(function, column) from `count` or `sum|min|max|mean:COLUMN`; the column of `count` is None."""
    function, colon, column = arg.partition(":")
    if arg == "count":
        return "count", None
    if function not in AGGREGATE_FUNCTIONS or not colon or not column:
        raise UsageError("group: unknown aggregate %r (use count, sum:COLUMN, min:COLUMN, max:COLUMN or mean:COLUMN)"
                         % arg)
    return function, column


def _aggregate(function, numbers):
    if function == "sum":
        return fmt_decimal(exact_sum(numbers))
    if function == "min":
        return fmt_decimal(min(numbers))
    if function == "max":
        return fmt_decimal(max(numbers))
    return fmt_ratio(exact_sum(numbers), len(numbers))


def cmd_group(args, opts):
    _need_min_args(args, 3, "group FILE BY AGGREGATE...")
    if len(set(args[2:])) != len(args[2:]):
        raise UsageError("group: aggregate %r given twice" % next(a for a in args[2:] if args[2:].count(a) > 1))
    aggregates = [parse_aggregate(a) for a in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    names = [args[1]] + [a.replace(":", "_") for a in args[2:]]
    if args[1] in names[1:]:
        raise TabulaError("%s: column %r would appear twice in the result" % (table.source, args[1]))
    positions = {column: table.index(column) for _, column in aggregates if column is not None}
    cells = {column: [] for column in positions}  # the numbers of each aggregated column, row by row
    for number, row in enumerate(table.rows, 1):
        for column, at in positions.items():
            cells[column].append(_need_cell_number(table, number, column, row[at]))
    groups = {}
    for i, row in enumerate(table.rows):
        groups.setdefault(row[by], []).append(i)
    rows = []
    for key, members in groups.items():
        out = [key]
        for function, column in aggregates:
            out.append(str(len(members)) if function == "count"
                       else _aggregate(function, [cells[column][i] for i in members]))
        rows.append(out)
    return Table(names, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    at_left, at_right = left.index(args[2]), right.index(args[2])
    kept = [i for i in range(len(right.columns)) if i != at_right]
    names = left.columns + [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i]
                            for i in kept]
    for name in names:
        if names.count(name) > 1:
            raise TabulaError("%s: column %r would appear twice in the result" % (left.source, name))
    matches = {}
    for row in right.rows:
        matches.setdefault(row[at_right], []).append([row[i] for i in kept])
    empty = [""] * len(kept)
    rows = []
    for row in left.rows:
        found = matches.get(row[at_left]) or ([empty] if opts["kind"] == "left" else [])
        rows.extend(row + extra for extra in found)
    return Table(names, rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    at_row, at_column, at_value = table.index(args[1]), table.index(args[2]), table.index(args[3])
    sums, columns = {}, {}  # the numbers per ROW value and COLUMN value; the COLUMN values in order of appearance
    for number, row in enumerate(table.rows, 1):
        label = row[at_column]
        if not label.strip():
            raise TabulaError("%s: row %d: column %r: empty value" % (table.source, number, args[2]))
        if label == args[1]:
            raise TabulaError("%s: column %r would appear twice in the result" % (table.source, label))
        cell = _need_cell_number(table, number, args[3], row[at_value])
        columns.setdefault(label, None)
